// RELEASE_MANIFEST_END
const SHELL_CACHE = `toeic-shell-${RELEASE}`;
const DICT_CACHE = 'toeic-dict-v1';
const EXTENDED_CACHE = 'toeic-dict-extended-v1';
const SUGGESTIONS_CACHE = 'toeic-suggestions-v1';
const REVERSE_CACHE = 'toeic-reverse-v1';   // 中文反查分片，最多保留 32 片
const FONT_CACHE = 'toeic-fonts-v1';
const LIB_CACHE = 'toeic-lib-v1';   // Firebase SDK（網址帶版本號，內容不會變）
const KEEP = [SHELL_CACHE, DICT_CACHE, EXTENDED_CACHE, SUGGESTIONS_CACHE, REVERSE_CACHE, FONT_CACHE, LIB_CACHE];
let limitedWrites = Promise.resolve();
const SCOPE = new URL('./', self.location.href);
const assetURL = (path) => new URL(path, SCOPE).href;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL_CACHE);
    try {
      // 限制並行數，避免大量同時下載。失敗的部分發布不會接手。
      const queue = Object.entries(ASSETS);
      const results = await Promise.allSettled(Array.from({length: 6}, async () => {
        while (queue.length) {
          const [path, expected] = queue.shift();
          const response = await verifiedAsset(path);
          await cache.put(assetURL(path), response);
        }
      }));
      const failed = results.find(r => r.status === 'rejected');
      if (failed) throw failed.reason;
    } catch (error) {
      await caches.delete(SHELL_CACHE);
      throw error;
    }
  })());
  // 不 skipWaiting／claim：舊分頁仍由完整舊版本處理。
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('toeic-') && !KEEP.includes(name)) await caches.delete(name);
    }

  })());
});

// 頁面載入完成後，把用到的檔案清單傳過來，一次存進快取（第一次開網站時 Service Worker 還沒接手）
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'cache-urls') {
    event.waitUntil(cacheUrls(event.data.urls || []));
  }
});

async function cacheUrls(urls) {
  const fonts = await caches.open(FONT_CACHE);
  await Promise.all(urls.map(async (u) => {
    try {
      const url = new URL(u, self.location.href);
      if (isFont(url)) {
        // 字型的 CSS（fonts.googleapis.com）是用 <link> 跨網站載入的「不透明」回應，要用 no-cors 抓；
        // 字型檔本身（fonts.gstatic.com）瀏覽器是用 CORS 方式要的，存的也必須是 CORS 回應，否則會被拒絕
        const mode = url.hostname === 'fonts.gstatic.com' ? 'cors' : 'no-cors';
        if (!(await fonts.match(url.href))) await fonts.put(url.href, await fetch(url.href, { mode }));
      }
    } catch (e) {
      // 單一檔案存不了不影響其他檔案
    }
  }));
}

function isFirebaseSdk(url) {
  return url.hostname === 'www.gstatic.com' && url.pathname.startsWith('/firebasejs/');
}

function isFont(url) {
  return url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com';
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (url.pathname.includes('/data/dict/suggestions-v1/')) {
      // 小型路由索引保留；候選詞分片最多 32 片，離線仍可找已快取的開頭。
      event.respondWith(cacheFirst(req, url.pathname.endsWith('/index.json') ? DICT_CACHE : SUGGESTIONS_CACHE, url.pathname.endsWith('/index.json') ? 0 : 32));
    } else if (url.pathname.includes('/data/dict/reverse-v1/')) event.respondWith(cacheFirst(req, REVERSE_CACHE, 32));
    else if (url.pathname.includes('/data/dict/extended-v1/')) event.respondWith(cacheFirst(req, EXTENDED_CACHE, 128));
    else if (url.pathname.includes('/data/dict/')) event.respondWith(cacheFirst(req, DICT_CACHE));
    else {
      const path = url.pathname.slice(SCOPE.pathname.length);
      if (req.mode === 'navigate' || Object.hasOwn(ASSETS, path)) {
        event.respondWith(releaseAsset(req.mode === 'navigate' ? 'index.html' : path));
      } else if (/\.(?:js|css|html)$/.test(path)) {
        // 完整發布之外的程式不能從網路混進正在執行的舊版。
        event.respondWith(Promise.resolve(new Response('請關閉網站分頁後重新開啟以更新', {status: 409})));
      }
    }
  } else if (isFont(url)) {
    event.respondWith(cacheFirst(req, FONT_CACHE));
  } else if (isFirebaseSdk(url)) {
    event.respondWith(cacheFirst(req, LIB_CACHE));
  }
  // 其他（Gemini、Free Dictionary、Firebase 的資料連線）不處理，照常連網
});

async function cacheFirst(req, cacheName, limit = 0) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok || res.type === 'opaque') {
    const copy = res.clone();
    const save = async () => {
      await cache.put(req, copy);
      if (limit) {
        const keys = await cache.keys();
        for (const key of keys.slice(0, Math.max(0, keys.length - limit))) await cache.delete(key);
      }
    };
    // 限量快取採 FIFO；串行寫入避免並行下載超過各自上限。
    if (limit) { limitedWrites = limitedWrites.then(save).catch(() => {}); await limitedWrites; }
    else await save().catch(() => {});
  }
  return res;
}

async function verifiedAsset(path) {
  const response = await fetch(assetURL(path), {cache: 'no-store'});
  if (!response.ok) throw new Error(`發布檔案無法下載：${path}`);
  const hash = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer())), x => x.toString(16).padStart(2, '0')).join('');
  if (hash !== ASSETS[path]) throw new Error(`發布版本不一致：${path}`);
  return response;
}

async function releaseAsset(path) {
  const cache = await caches.open(SHELL_CACHE);
  const hit = await cache.match(assetURL(path));
  if (hit) return hit;
  try {const response = await verifiedAsset(path);await cache.put(assetURL(path),response.clone());return response;} catch {}
  return new Response('離線檔案已被瀏覽器清除，請重新連線並關閉所有網站分頁後再開啟。', {status: 503});
}
